    if "-" not in isbn:
        raise ValueError("Invalid ISBN format. ISBN should be \"x-xxx-xxxxx-x\".")
    isbn_parts = isbn.split("-")
    if len(isbn_parts) != 4:
        raise ValueError("Invalid ISBN format. ISBN should be \"x-xxx-xxxxx-x\".")
    if not isbn_parts[0].isdigit():
        raise ValueError("Invalid ISBN format. ISBN should be \"x-xxx-xxxxx-x\".")
    for part in isbn_parts[1:-1]:
        if not part.isdigit() or len(part) != 3:
            raise ValueError("Invalid ISBN format. ISBN should be \"x-xxx-xxxxx-x\".")
    if not isbn_parts[-1].isdigit() and isbn_parts[-1] != "X":
        raise ValueError("Invalid ISBN format. ISBN should be \"x-xxx-xxxxx-x\".")
    checksum = 0
    for i, c in enumerate(isbn_parts[0]):
        checksum += c * (i + 1)
    for i, c in enumerate(isbn_parts[1]):
        checksum += c * (i + 2)
    for i, c in enumerate(isbn_parts[2]):
        checksum += c * (i + 3)
    checksum %= 11
